package calc

import (
	"errors"
	"testing"
)

// The native flavor's parser, generated by the real galop, parses input.
func TestParse(t *testing.T) {
	prog, err := ParseProg(CalcLex("1 + 22 - 3"))
	if err != nil {
		t.Fatal(err)
	}
	if got := len(prog.Expr().AllINT()); got != 3 {
		t.Errorf("INT tokens: got %d, want 3", got)
	}
	if got, want := prog.ToStringTree(), "(prog (expr 1 + 22 - 3) <EOF>)"; got != want {
		t.Errorf("tree: got %s, want %s", got, want)
	}
}

func TestSyntaxError(t *testing.T) {
	_, err := ParseProg(CalcLex("1 +"))
	var se *CalcSyntaxError
	if !errors.As(err, &se) {
		t.Fatalf("got %v (%T), want a *CalcSyntaxError", err, err)
	}
}

// From galop 0.3.0, ParseProgWithRecovery recovers from syntax errors as
// ANTLR's default error strategy does: every error, and a recovered tree.
func TestRecovery(t *testing.T) {
	prog, errs := ParseProgWithRecovery(CalcLex("1 + + 2 3"))
	if !prog.Ok() {
		t.Fatal("no recovered tree")
	}
	var msgs []string
	for _, e := range errs {
		msgs = append(msgs, e.Error())
	}
	if len(msgs) < 2 {
		t.Errorf("errors: got %q, want at least two", msgs)
	}
	if len(prog.Tree().ErrorKids) == 0 {
		t.Errorf("tree %s has no error tokens", prog.ToStringTree())
	}
	clean, errs := ParseProgWithRecovery(CalcLex("1 + 2"))
	if len(errs) != 0 || clean.ToStringTree() != "(prog (expr 1 + 2) <EOF>)" {
		t.Errorf("clean input: got %s and %v", clean.ToStringTree(), errs)
	}
}

// From galop 0.3.1, each error says how far the parse had read (Read), and
// the lexer says which token each token recognition error comes before
// (ErrorAt), so the two can be interleaved as ANTLR reports them.
func TestReadExtent(t *testing.T) {
	ts := CalcLex("1 + # + 2")
	if len(ts.Errors) != 1 || len(ts.ErrorAt) != 1 {
		t.Fatalf("lexical errors %v at %v, want one", ts.Errors, ts.ErrorAt)
	}
	prog, errs := ParseProgWithRecovery(ts)
	if len(errs) == 0 {
		t.Fatal("no syntax error")
	}
	if errs[0].Read < errs[0].Token {
		t.Errorf("Read %d before the error's token %d", errs[0].Read, errs[0].Token)
	}
	if r := prog.Tree().Read; r != len(ts.Tokens)-1 {
		t.Errorf("Tree.Read %d, want EOF's index %d", r, len(ts.Tokens)-1)
	}
}
